      const currentDateInLoop = uniqueDates[i];
      const expectedDateStr = checkDate.toISOString().split('T')[0];

      if (currentDateInLoop === expectedDateStr) {
        streak++;
        checkDate.setDate(checkDate.getDate() - 1); // Move to the previous day
      } else {
        break; 
      }
    }
    return streak;
  }

