async (e) => {
    e.preventDefault();

    if (!validateRegisterForm()) {
      return;
    }

    setLoading(true);
    setError("");
    setSuccess("");

    try {
      const data = await register({ username, email, password });

      if (data.success) {
        setSuccess("Account created successfully! Redirecting to login...");
        
        setUsername("");
        setEmail("");
        setPassword("");
        setConfirmPassword("");
        setErrors({});

        setTimeout(() => {
          setTab("login");
          setSuccess("");
        }, 2000);
      }
    } catch (err) {
      setError(err.message || "Registration failed. Please try again.");
    } finally {
      setLoading(false);
    }
  }

